const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Članovi</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Njemački član ne podudara se uvijek s rodom riječi u bosanskom jeziku. Zato je imenice najbolje učiti zajedno s članom.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Primjeri članova</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — sto</div>\n      <div class=\"kurss-example\">die Tür — vrata</div>\n      <div class=\"kurss-example\">das Messer — nož</div>\n      <div class=\"kurss-example\">das Mädchen — djevojčica</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Često DER</h4>\n    <p class=\"artikuli-explain\">DER je često uz osobe muškog roda, dane, mjesece, godišnja doba i neke riječi s određenim nastavcima.</p>\n\n    <h5 class=\"artikuli-subtitle\">Pravila</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → često DER, na primjer: der Computer, der Lehrer <span class=\"artikuli-note\">ali ne uvijek</span></div>\n      <div class=\"kurss-example\">-ling → često DER, na primjer: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → često DER, na primjer: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">osobe muškog roda → der Mann, der Vater</div>\n      <div class=\"kurss-example\">zanimanja → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">marke automobila → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">dani → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">mjeseci → der August, der Dezember</div>\n      <div class=\"kurss-example\">godišnja doba → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Primjeri</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — muškarac</div>\n      <div class=\"kurss-example\">der Vater — otac</div>\n      <div class=\"kurss-example\">der Montag — ponedjeljak</div>\n      <div class=\"kurss-example\">der August — august</div>\n      <div class=\"kurss-example\">der Sommer — ljeto</div>\n      <div class=\"kurss-example\">der Lehrer — učitelj</div>\n      <div class=\"kurss-example\">der Computer — računar</div>\n      <div class=\"kurss-example\">der Schmetterling — leptir</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Često DIE</h4>\n    <p class=\"artikuli-explain\">DIE je često uz osobe ženskog roda, množinu i riječi s nastavcima -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Pravila</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">osobe ženskog roda → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">marke motocikala → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">množina → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">množina gotovo uvijek → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Primjeri</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — žena</div>\n      <div class=\"kurss-example\">die Mutter — majka</div>\n      <div class=\"kurss-example\">die Wohnung — stan</div>\n      <div class=\"kurss-example\">die Rechnung — račun</div>\n      <div class=\"kurss-example\">die Freiheit — sloboda</div>\n      <div class=\"kurss-example\">die Möglichkeit — mogućnost</div>\n      <div class=\"kurss-example\">die Mannschaft — tim / ekipa</div>\n      <div class=\"kurss-example\">die Nation — nacija</div>\n      <div class=\"kurss-example\">die Universität — univerzitet</div>\n      <div class=\"kurss-example\">die Polizei — policija</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Često DAS</h4>\n    <p class=\"artikuli-explain\">DAS je često uz umanjenice na -chen / -lein, mnoge riječi na -ment / -um i glagole upotrijebljene kao imenice.</p>\n\n    <h5 class=\"artikuli-subtitle\">Pravila</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metali → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">hemijski elementi → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hoteli → das Hotel</div>\n      <div class=\"kurss-example\">boje kao imenice → das Rot, das Blau</div>\n      <div class=\"kurss-example\">glagol kao imenica → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">glagoli kao imenice → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Primjeri</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — dijete</div>\n      <div class=\"kurss-example\">das Mädchen — djevojčica</div>\n      <div class=\"kurss-example\">das Häuschen — kućica</div>\n      <div class=\"kurss-example\">das Instrument — instrument</div>\n      <div class=\"kurss-example\">das Zentrum — centar</div>\n      <div class=\"kurss-example\">das Museum — muzej</div>\n      <div class=\"kurss-example\">das Essen — jelo / hrana</div>\n      <div class=\"kurss-example\">das Lernen — učenje</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Važni izuzeci / učiti zajedno s članom</h4>\n    <p class=\"artikuli-explain\">Kod nekih riječi član se ne može pouzdano odrediti prema nastavku ili prema rodu riječi u bosanskom jeziku. Njih je najbolje učiti zajedno s članom.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — vrata</div>\n      <div class=\"kurss-example\">das Messer — nož</div>\n      <div class=\"kurss-example\">die Sonne — sunce</div>\n      <div class=\"kurss-example\">der Mond — mjesec</div>\n      <div class=\"kurss-example\">das Mädchen — djevojčica</div>\n      <div class=\"kurss-example\">das Auto — automobil</div>\n      <div class=\"kurss-example\">der Käse — sir</div>\n      <div class=\"kurss-example\">die Gabel — viljuška</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nastavci i grupe riječi pomažu da pogodiš član, ali nisu 100% sigurno pravilo. Ako nisi siguran, uči riječ zajedno s članom.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Zamjenice</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ i Dativ — oblici zamjenica.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — ko?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — ja</div><div class=\"kurss-example\">du — ti</div><div class=\"kurss-example\">er — on</div><div class=\"kurss-example\">sie — ona</div><div class=\"kurss-example\">es — ono</div><div class=\"kurss-example\">wir — mi</div><div class=\"kurss-example\">ihr — vi</div><div class=\"kurss-example\">sie — oni / one</div><div class=\"kurss-example\">Sie — Vi (formalno)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — koga?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mene / me</div><div class=\"kurss-example\">dich — tebe / te</div><div class=\"kurss-example\">ihn — njega / ga (m.)</div><div class=\"kurss-example\">sie — nju / je (ž.)</div><div class=\"kurss-example\">es — njega / ga</div><div class=\"kurss-example\">uns — nas</div><div class=\"kurss-example\">euch — vas</div><div class=\"kurss-example\">sie — njih / ih</div><div class=\"kurss-example\">Sie — Vas (formalno)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — kome?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — meni / mi</div><div class=\"kurss-example\">dir — tebi / ti</div><div class=\"kurss-example\">ihm — njemu / mu</div><div class=\"kurss-example\">ihr — njoj / joj</div><div class=\"kurss-example\">uns — nama / nam</div><div class=\"kurss-example\">euch — vama / vam</div><div class=\"kurss-example\">ihnen — njima / im</div><div class=\"kurss-example\">Ihnen — Vama / Vam (formalno)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Kako odabrati oblik?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — subjekat (ko vrši radnju?)</li><li><span class=\"case-red\">Akkusativ</span> — direktni objekat (koga?)</li><li><span class=\"case-green\">Dativ</span> — indirektni objekat (kome?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Primjeri</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Vidim te.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Vidim ga.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Sviđate nam se.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Pomažem ti.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Dajem mu knjigu.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Zahvaljujemo vam.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ je uvijek subjekat, a Akkusativ i Dativ — objekti. Pogledaj glagol i pitaj: <span class=\"case-red\">koga?</span> ili <span class=\"case-green\">kome?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Samoglasnici — dugi i kratki</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>U njemačkom jeziku samoglasnici mogu biti dugi ili kratki. To utiče na izgovor riječi.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Dugi samoglasnik</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">warm (varm) — topao</div><div class=\"kurss-example\">gut (gūt) — dobar</div><div class=\"kurss-example\">Tat (tāt) — djelo / postupak</div><div class=\"kurss-example\">Flur (flūr) — hodnik</div><div class=\"kurss-example\">Weg (vēk) — put</div><div class=\"kurss-example\">Hut (hūt) — šešir</div><div class=\"kurss-example\">Hof (hōf) — dvorište</div><div class=\"kurss-example\">Schlaf (šlāf) — san</div></div>\n              <p class=\"artikuli-explain\">Ako iza samoglasnika slijedi jedan suglasnik, samoglasnik se često izgovara dugo.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kratki samoglasnik</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Pilz (pilc) — gljiva</div><div class=\"kurss-example\">Wort (vort) — riječ</div><div class=\"kurss-example\">Mund (munt) — usta</div><div class=\"kurss-example\">bald (balt) — uskoro</div><div class=\"kurss-example\">scharf (šarf) — oštar</div><div class=\"kurss-example\">Feld (felt) — polje</div><div class=\"kurss-example\">voll (fol) — pun</div></div>\n              <p class=\"artikuli-explain\">Ako iza samoglasnika slijede dva ili više suglasnika, samoglasnik se često izgovara kratko.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Završeci en / el / er</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">singen (zingen) — pjevati</div><div class=\"kurss-example\">tragen (trāgen) — nositi</div><div class=\"kurss-example\">Garten (garten) — bašta / vrt</div><div class=\"kurss-example\">Vogel (fōgel) — ptica</div><div class=\"kurss-example\">Segel (zēgel) — jedro</div><div class=\"kurss-example\">Braten (brāten) — pečenje</div><div class=\"kurss-example\">Bogen (bōgen) — luk</div><div class=\"kurss-example\">Spiegel (špīgel) — ogledalo</div><div class=\"kurss-example\">Finger (finger) — prst</div><div class=\"kurss-example\">Halter (halter) — držač</div><div class=\"kurss-example\">Arbeiter (arbajter) — radnik</div><div class=\"kurss-example\">Häuser (hojzer) — kuće</div><div class=\"kurss-example\">wieder (vīder) — opet</div><div class=\"kurss-example\">breiter (brajter) — širi</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Slovo h kao oznaka dužine</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rahmen (rāmen) — okvir</div><div class=\"kurss-example\">Ohr (ōr) — uho</div><div class=\"kurss-example\">Kohle (kōle) — ugalj</div><div class=\"kurss-example\">Zahl (cāl) — broj</div><div class=\"kurss-example\">ihn (īn) — njega</div><div class=\"kurss-example\">ihm (īm) — njemu</div><div class=\"kurss-example\">Huhn (hūn) — kokoš</div><div class=\"kurss-example\">nahm (nām) — uzeo / uze</div><div class=\"kurss-example\">nehmen (nēmen) — uzeti / uzimati</div><div class=\"kurss-example\">Schuh (šū) — cipela</div></div>\n              <p class=\"artikuli-explain\">U nekim riječima h produžava prethodni samoglasnik. U takvim slučajevima se h obično ne izgovara.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Završeci na e</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Lampe (lampe) — lampa</div><div class=\"kurss-example\">Hase (hāze) — zec</div><div class=\"kurss-example\">Knabe (knābe) — dječak</div><div class=\"kurss-example\">Rabe (rābe) — gavran</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Dugo i = ie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">die (dī) — član „die“</div><div class=\"kurss-example\">diese (dīze) — ova / ovi</div><div class=\"kurss-example\">wieder (vīder) — opet</div><div class=\"kurss-example\">Fliege (flīge) — muha</div><div class=\"kurss-example\">Ziege (cīge) — koza</div><div class=\"kurss-example\">Stiel (štīl) — drška / stabljika</div><div class=\"kurss-example\">Dieb (dīp) — lopov</div><div class=\"kurss-example\">hier (hīr) — ovdje</div></div>\n              <p class=\"artikuli-explain\">Dugo i se u njemačkom jeziku često piše kao ie.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Udvojeni samoglasnici</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Saal (zāl) — dvorana</div><div class=\"kurss-example\">Saat (zāt) — sjetva / sjeme</div><div class=\"kurss-example\">Staat (štāt) — država</div><div class=\"kurss-example\">Beere (bēre) — bobica</div><div class=\"kurss-example\">See (zē) — jezero / more</div><div class=\"kurss-example\">Beet (bēt) — gredica / leja</div><div class=\"kurss-example\">Boot (bōt) — čamac</div><div class=\"kurss-example\">Moor (mōr) — močvara</div><div class=\"kurss-example\">Moos (mōs) — mahovina</div></div>\n              <p class=\"artikuli-explain\">Udvojeni samoglasnici se obično izgovaraju dugo.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Wand (vant) — zid</div><div class=\"kurss-example\">Wände (vende) — zidovi</div><div class=\"kurss-example\">Vater (fāter) — otac</div><div class=\"kurss-example\">Väter (fēter) — očevi</div><div class=\"kurss-example\">Schrank (šrank) — ormar</div><div class=\"kurss-example\">Schränke (šrenke) — ormari</div><div class=\"kurss-example\">Bank (bank) — klupa / banka</div><div class=\"kurss-example\">Bänke (benke) — klupe</div><div class=\"kurss-example\">Tal (tāl) — dolina</div><div class=\"kurss-example\">Täler (tēler) — doline</div></div>\n              <p class=\"artikuli-explain\">ä je preglas (umlaut) od a.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ö</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rose (rōze) — ruža</div><div class=\"kurss-example\">Röschen (rēshen) — ružica</div><div class=\"kurss-example\">Ofen (ōfen) — peć</div><div class=\"kurss-example\">Öfen (ēfen) — peći</div><div class=\"kurss-example\">Rock (rok) — suknja</div><div class=\"kurss-example\">Röcke (reke) — suknje</div></div>\n              <p class=\"artikuli-explain\">ö je preglas (umlaut) od o.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ü</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kurz (kurc) — kratak</div><div class=\"kurss-example\">kürzer (kircer) — kraći</div><div class=\"kurss-example\">Kunst (kunst) — umjetnost</div><div class=\"kurss-example\">Künste (kinste) — umjetnosti</div><div class=\"kurss-example\">Mutter (muter) — majka</div><div class=\"kurss-example\">Mütter (miter) — majke</div></div>\n              <p class=\"artikuli-explain\">ü je preglas (umlaut) od u.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Dvoglasi: äu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Baum (baum) — drvo</div><div class=\"kurss-example\">Bäume (bojme) — drveća / stabla</div><div class=\"kurss-example\">Haus (haus) — kuća</div><div class=\"kurss-example\">Häuser (hojzer) — kuće</div><div class=\"kurss-example\">Strauch (štrauh) — grm</div><div class=\"kurss-example\">Sträucher (štrojher) — grmovi</div><div class=\"kurss-example\">Maus (maus) — miš</div><div class=\"kurss-example\">Mäuse (mojze) — miševi</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Dvoglasi: eu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">heute (hojte) — danas</div><div class=\"kurss-example\">Leute (lojte) — ljudi</div><div class=\"kurss-example\">neu (noj) — nov</div><div class=\"kurss-example\">neun (nojn) — devet</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Dvoglasi: ei</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">mein (majn) — moj</div><div class=\"kurss-example\">dein (dajn) — tvoj</div><div class=\"kurss-example\">sein (zajn) — njegov / biti</div><div class=\"kurss-example\">frei (fraj) — slobodan</div><div class=\"kurss-example\">arbeiten (arbajten) — raditi</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Napomene o izgovoru iz 2. lekcije</h4>\n              <ul class=\"kurss-summary-list\"><li>u riječima ich, nicht, rechnen, zeichnen „ch“ se izgovara meko (kao blago, meko „h“)</li><li>u riječima arbeiten i zeichnen „ei“ se izgovara kao „aj“</li><li>„sp“ se na početku riječi izgovara kao „šp“</li><li>u glagolu tun slovo „u“ se izgovara dugo</li></ul>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Sažetak</h4>\n              <ul class=\"kurss-summary-list\"><li>jedan suglasnik iza samoglasnika → često dug samoglasnik</li><li>dva ili više suglasnika → često kratak samoglasnik</li><li>h može produžiti samoglasnik</li><li>ie često označava dugo i</li><li>udvojeni samoglasnici su obično dugi</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Suglasnici i kombinacije slova</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>U njemačkom jeziku neki suglasnici i kombinacije slova izgovaraju se drugačije nego što se pišu. U ovoj lekciji su najvažniji primjeri za početnike.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Suglasnici</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">das Rad (rāt) — točak</div><div class=\"kurss-example\">die Räder (rēder) — točkovi</div><div class=\"kurss-example\">Bad (bāt) — kupka / kupatilo</div><div class=\"kurss-example\">Bäder (bēder) — kupatila</div></div>\n              <p class=\"artikuli-explain\">Na kraju riječi suglasnici se često ne izgovaraju onako kako se pišu.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ch</h4>\n              <p class=\"artikuli-explain\">„ch“ se može izgovarati meko ili tvrdo. U nekim riječima zvuči kao meko „h“, u drugim kao tvrdo „h“ (bliže „k“).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">rechnen (rehnen) — računati</div><div class=\"kurss-example\">zeichnen (cajhnen) — crtati</div><div class=\"kurss-example\">nicht (niht) — ne</div><div class=\"kurss-example\">schlecht (šleht) — loš</div><div class=\"kurss-example\">mich (mih) — mene</div><div class=\"kurss-example\">dich (dih) — tebe</div><div class=\"kurss-example\">Strauch (štrauh) — grm</div><div class=\"kurss-example\">noch (noh) — još</div><div class=\"kurss-example\">Nacht (naht) — noć</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sch</h4>\n              <p class=\"artikuli-explain\">„sch“ se u njemačkom jeziku izgovara kao bosansko „š“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Schule (šūle) — škola</div><div class=\"kurss-example\">Schüler (šīler) — učenik</div><div class=\"kurss-example\">Schiff (šif) — brod</div><div class=\"kurss-example\">Schraube (šraube) — vijak / šaraf</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sp i st na početku riječi</h4>\n              <p class=\"artikuli-explain\">Na početku riječi ili sloga „sp“ se često izgovara kao „šp“, a „st“ kao „št“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen (špīlen) — igrati (se)</div><div class=\"kurss-example\">Sprung (šprung) — skok</div><div class=\"kurss-example\">stehen (štēen) — stajati</div><div class=\"kurss-example\">Stall (štal) — štala</div><div class=\"kurss-example\">Stand (štant) — štand / stanje</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>qu</h4>\n              <p class=\"artikuli-explain\">„qu“ se u njemačkom jeziku obično izgovara kao „kv“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Qual (kvāl) — muka</div><div class=\"kurss-example\">Quartier (kvartīr) — smještaj / četvrt</div><div class=\"kurss-example\">quer (kvēr) — poprijeko</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>s i z</h4>\n              <p class=\"artikuli-explain\">Na početku riječi „s“ često zvuči kao „z“. Slovo „z“ u njemačkom jeziku zvuči kao bosansko „c“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">sagen (zāgen) — reći</div><div class=\"kurss-example\">singen (zingen) — pjevati</div><div class=\"kurss-example\">Rose (rōze) — ruža</div><div class=\"kurss-example\">Zahl (cāl) — broj</div><div class=\"kurss-example\">Zeit (cajt) — vrijeme</div><div class=\"kurss-example\">Zink (cink) — cink</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>v</h4>\n              <p class=\"artikuli-explain\">U njemačkom jeziku „v“ se često izgovara kao „f“. U riječima stranog porijekla često zvuči kao bosansko „v“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Vater (fāter) — otac</div><div class=\"kurss-example\">von (fon) — od</div><div class=\"kurss-example\">viel (fīl) — mnogo</div><div class=\"kurss-example\">vier (fīr) — četiri</div><div class=\"kurss-example\">Villa (vila) — vila</div><div class=\"kurss-example\">Klavier (klavīr) — klavir</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>x i y</h4>\n              <p class=\"artikuli-explain\">„x“ se izgovara kao „ks“. „y“ se u nekim riječima izgovara kao „ü“ (približno kao „i“ sa zaobljenim usnama).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Felix (fēliks) — Feliks</div><div class=\"kurss-example\">Axt (akst) — sjekira</div><div class=\"kurss-example\">Mystik (mistik) — mistika</div><div class=\"kurss-example\">Mythe (mīte) — mit</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ß</h4>\n              <p class=\"artikuli-explain\">„ß“ se u njemačkom jeziku izgovara kao „s“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Fuß (fūs) — stopalo</div><div class=\"kurss-example\">Füße (fīse) — stopala</div><div class=\"kurss-example\">Grüße (grīse) — pozdravi</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Sažetak</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → š</li><li>sp / st na početku → šp / št</li><li>qu → kv</li><li>z → c</li><li>v često → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Osnove glagola</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Glagoli iz 1. časa i njihovi oblici (konjugacija)</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Glagoli</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kommen — dolaziti</div><div class=\"kurss-example\">gehen — ići</div><div class=\"kurss-example\">stehen — stajati</div><div class=\"kurss-example\">singen — pjevati</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>kommen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich komme — ja dolazim</div><div class=\"kurss-example\">du kommst — ti dolaziš</div><div class=\"kurss-example\">er kommt — on dolazi</div><div class=\"kurss-example\">sie kommt — ona dolazi</div><div class=\"kurss-example\">wir kommen — mi dolazimo</div><div class=\"kurss-example\">ihr kommt — vi dolazite</div><div class=\"kurss-example\">sie kommen — oni / one dolaze</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>gehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich gehe — ja idem</div><div class=\"kurss-example\">du gehst — ti ideš</div><div class=\"kurss-example\">er geht — on ide</div><div class=\"kurss-example\">sie geht — ona ide</div><div class=\"kurss-example\">wir gehen — mi idemo</div><div class=\"kurss-example\">ihr geht — vi idete</div><div class=\"kurss-example\">sie gehen — oni / one idu</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>stehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich stehe — ja stojim</div><div class=\"kurss-example\">du stehst — ti stojiš</div><div class=\"kurss-example\">er steht — on stoji</div><div class=\"kurss-example\">sie steht — ona stoji</div><div class=\"kurss-example\">wir stehen — mi stojimo</div><div class=\"kurss-example\">ihr steht — vi stojite</div><div class=\"kurss-example\">sie stehen — oni / one stoje</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>singen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich singe — ja pjevam</div><div class=\"kurss-example\">du singst — ti pjevaš</div><div class=\"kurss-example\">er singt — on pjeva</div><div class=\"kurss-example\">sie singt — ona pjeva</div><div class=\"kurss-example\">wir singen — mi pjevamo</div><div class=\"kurss-example\">ihr singt — vi pjevate</div><div class=\"kurss-example\">sie singen — oni / one pjevaju</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Glagoli iz 2. časa</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen — igrati</div><div class=\"kurss-example\">arbeiten — raditi</div><div class=\"kurss-example\">fragen — pitati</div><div class=\"kurss-example\">antworten — odgovarati</div><div class=\"kurss-example\">rechnen — računati</div><div class=\"kurss-example\">zeichnen — crtati</div><div class=\"kurss-example\">tun — činiti</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>spielen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich spiele — ja igram</div><div class=\"kurss-example\">du spielst — ti igraš</div><div class=\"kurss-example\">er spielt — on igra</div><div class=\"kurss-example\">sie spielt — ona igra</div><div class=\"kurss-example\">wir spielen — mi igramo</div><div class=\"kurss-example\">ihr spielt — vi igrate</div><div class=\"kurss-example\">sie spielen — oni / one igraju</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>arbeiten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich arbeite — ja radim</div><div class=\"kurss-example\">du arbeitest — ti radiš</div><div class=\"kurss-example\">er arbeitet — on radi</div><div class=\"kurss-example\">sie arbeitet — ona radi</div><div class=\"kurss-example\">wir arbeiten — mi radimo</div><div class=\"kurss-example\">ihr arbeitet — vi radite</div><div class=\"kurss-example\">sie arbeiten — oni / one rade</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>fragen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich frage — ja pitam</div><div class=\"kurss-example\">du fragst — ti pitaš</div><div class=\"kurss-example\">er fragt — on pita</div><div class=\"kurss-example\">sie fragt — ona pita</div><div class=\"kurss-example\">wir fragen — mi pitamo</div><div class=\"kurss-example\">ihr fragt — vi pitate</div><div class=\"kurss-example\">sie fragen — oni / one pitaju</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>antworten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich antworte — ja odgovaram</div><div class=\"kurss-example\">du antwortest — ti odgovaraš</div><div class=\"kurss-example\">er antwortet — on odgovara</div><div class=\"kurss-example\">sie antwortet — ona odgovara</div><div class=\"kurss-example\">wir antworten — mi odgovaramo</div><div class=\"kurss-example\">ihr antwortet — vi odgovarate</div><div class=\"kurss-example\">sie antworten — oni / one odgovaraju</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>rechnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich rechne — ja računam</div><div class=\"kurss-example\">du rechnest — ti računaš</div><div class=\"kurss-example\">er rechnet — on računa</div><div class=\"kurss-example\">sie rechnet — ona računa</div><div class=\"kurss-example\">wir rechnen — mi računamo</div><div class=\"kurss-example\">ihr rechnet — vi računate</div><div class=\"kurss-example\">sie rechnen — oni / one računaju</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>zeichnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich zeichne — ja crtam</div><div class=\"kurss-example\">du zeichnest — ti crtaš</div><div class=\"kurss-example\">er zeichnet — on crta</div><div class=\"kurss-example\">sie zeichnet — ona crta</div><div class=\"kurss-example\">wir zeichnen — mi crtamo</div><div class=\"kurss-example\">ihr zeichnet — vi crtate</div><div class=\"kurss-example\">sie zeichnen — oni / one crtaju</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>tun</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich tue — ja činim</div><div class=\"kurss-example\">du tust — ti činiš</div><div class=\"kurss-example\">er tut — on čini</div><div class=\"kurss-example\">sie tut — ona čini</div><div class=\"kurss-example\">wir tun — mi činimo</div><div class=\"kurss-example\">ihr tut — vi činite</div><div class=\"kurss-example\">sie tun — oni / one čine</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Građa rečenice</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>U upitnoj rečenici glagol u njemačkom jeziku obično stoji na prvom mjestu.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Primjeri</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Du kommst. — Ti dolaziš.</div><div class=\"kurss-example\">Kommst du? — Dolaziš li?</div><div class=\"kurss-example\">Er singt. — On pjeva.</div><div class=\"kurss-example\">Singt er? — Pjeva li on?</div><div class=\"kurss-example\">Stehst du? — Stojiš li?</div><div class=\"kurss-example\">Ja, ich stehe. — Da, stojim.</div><div class=\"kurss-example\">Geht ihr? — Idete li?</div><div class=\"kurss-example\">Ja, wir gehen. — Da, idemo.</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Pitanja s „was“</h4>\n              <p class=\"artikuli-explain\">Ako pitanje počinje upitnom riječju, glagol u njemačkom jeziku obično stoji odmah iza upitne riječi.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Was tust du? — Šta ti radiš?</div><div class=\"kurss-example\">Was tut er? — Šta on radi?</div><div class=\"kurss-example\">Was tut sie? — Šta ona radi?</div><div class=\"kurss-example\">Was tun sie? — Šta oni / one rade?</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Negacija s „nicht“</h4>\n              <p class=\"artikuli-explain\">Ako se negacija „nicht“ odnosi na glagol, ona u njemačkom jeziku obično stoji iza glagola.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich spiele nicht. — Ja ne igram.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul ne pita.</div><div class=\"kurss-example\">Er kommt nicht. — On ne dolazi.</div><div class=\"kurss-example\">Sie singen nicht. — Oni / one ne pjevaju.</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Rečenice iz 2. lekcije</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Spielst du? — Igraš li?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Ne, ne igram, radim.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul ne pita, on radi.</div><div class=\"kurss-example\">Arbeitest du? — Radiš li?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Ne, ne radim, pjevam.</div><div class=\"kurss-example\">Was tut Paul? — Šta radi Paul?</div><div class=\"kurss-example\">Er spielt. — On igra.</div><div class=\"kurss-example\">Was tut Marie? — Šta radi Marie?</div><div class=\"kurss-example\">Sie singt. — Ona pjeva.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul igra, a Marie pjeva.</div><div class=\"kurss-example\">Singt ihr? — Pjevate li?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Ne, ne pjevamo, radimo.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Šta rade Paul i Marie?</div><div class=\"kurss-example\">Sie fragen. — Oni pitaju.</div><div class=\"kurss-example\">Sie antworten nicht. — Oni ne odgovaraju.</div><div class=\"kurss-example\">Wer arbeitet? — Ko radi?</div><div class=\"kurss-example\">Wir arbeiten. — Mi radimo.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Mi računamo i crtamo.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Oni / one dolaze, pitaju, odgovaraju, rade, igraju, pjevaju i idu.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Lekcija 2</h3>\n            <p class=\"kurss-lesson-intro\">Druga lekcija: dijalozi, riječi, izgovor, gramatika i prevođenje.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dijalozi / rečenice</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Riječi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — igrati se; svirati</div>\n                  <div class=\"kurss-example\">nein — ne</div>\n                  <div class=\"kurss-example\">nicht — ne</div>\n                  <div class=\"kurss-example\">arbeiten — raditi</div>\n                  <div class=\"kurss-example\">fragen — pitati</div>\n                  <div class=\"kurss-example\">was tut er? — šta on radi?</div>\n                  <div class=\"kurss-example\">was tun sie? — šta oni / one rade?</div>\n                  <div class=\"kurss-example\">aber — ali</div>\n                  <div class=\"kurss-example\">antworten — odgovarati</div>\n                  <div class=\"kurss-example\">rechnen — računati</div>\n                  <div class=\"kurss-example\">zeichnen — crtati</div>\n                  <div class=\"kurss-example\">Marie — Marija</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izgovor</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">U riječima ich, nicht, rechnen, zeichnen glas ch izgovara se meko, otprilike kao h izgovoreno zajedno s j, slično kao „hj“.</div><div class=\"kurss-example\">U riječima arbeiten, zeichnen diftong ei izgovara se otprilike kao bosansko „aj“.</div><div class=\"kurss-example\">Suglasnički skup sp izgovara se kao šp: spielen (špilen).</div><div class=\"kurss-example\">U glagolu tun u se izgovara dugo u svim licima.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Nastavci s e</h4>\n                  <div class=\"lesson1-grammar-note\">Ako osnova glagola završava na t, d, chn, onda u konjugaciji ispred nastavaka -st i -t stoji e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Upitna riječ</h4>\n                  <div class=\"lesson1-grammar-note\">U upitnim rečenicama koje počinju upitnom riječi, npr.: šta? ko? koji? zašto? zbog čega? itd., glagol stoji odmah iza upitne riječi.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Šta radiš?</div><div class=\"kurss-example\">Was tut er? — Šta on radi?</div><div class=\"kurss-example\">Was tut sie? — Šta ona radi?</div><div class=\"kurss-example\">Was tun sie? — Šta oni / one rade?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Negacija s nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Ako se negacija nicht odnosi na glagol, riječ negacije stoji iza glagola.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — On ne dolazi.</div><div class=\"kurss-example\">Sie singen nicht. — Oni ne pjevaju.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prevedi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 2: kartica za prevođenje\">\n                    <span class=\"lesson1-training-progress\">Lekcija 2 · Prevedi: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Ko pita?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klikni na karticu da vidiš njemački prijevod. Nakon odgovora sljedeći klik prikazuje sljedeću karticu.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Lekcija 6</h3>\n    <p class=\"kurss-lesson-intro\">Brojevi, množina, umlauti i oblici množine imenica.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dijalozi / rečenice</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Riječi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — nalazi se, ima, leži</div><div class=\"kurss-example\">der Bleistift (blajštift) — olovka</div><div class=\"kurss-example\">einige (ajnige) — nekoliko</div><div class=\"kurss-example\">hinlegen — odložiti</div><div class=\"kurss-example\">legt hin — odlaže</div><div class=\"kurss-example\">wieder (vider) — opet</div><div class=\"kurss-example\">aufmachen — otvoriti</div><div class=\"kurss-example\">er macht auf — on otvara</div><div class=\"kurss-example\">anspitzen (anšpicen) — šiljiti</div><div class=\"kurss-example\">er spitzt an — on šilji</div><div class=\"kurss-example\">sich setzen — sjesti</div><div class=\"kurss-example\">setzt sich — sjeda</div><div class=\"kurss-example\">der Schlüssel (šlisel) — ključ</div><div class=\"kurss-example\">das Fenster (fenster) — prozor</div><div class=\"kurss-example\">die Tafel (di tafel) — tabla</div><div class=\"kurss-example\">der Garten — bašča</div><div class=\"kurss-example\">der Löffel — kašika</div><div class=\"kurss-example\">zählen (celen) — brojati</div><div class=\"kurss-example\">die Nadel — igla</div><div class=\"kurss-example\">was ist das — šta je to?</div><div class=\"kurss-example\">der Hammer — čekić</div><div class=\"kurss-example\">die Hämmer — čekići</div><div class=\"kurss-example\">der Deckel (der dekel) — poklopac</div><div class=\"kurss-example\">der Teller — tanjir</div><div class=\"kurss-example\">der Wagen — kola</div><div class=\"kurss-example\">der Schlitten — sanke, saonice</div><div class=\"kurss-example\">das Ding — stvar</div><div class=\"kurss-example\">die Dinge — stvari</div><div class=\"kurss-example\">wie sind die Dinge? — kakve su stvari?</div><div class=\"kurss-example\">voll (fol) — pun</div><div class=\"kurss-example\">leer (ler) — prazan</div><div class=\"kurss-example\">schwer (šver) — težak, teško</div><div class=\"kurss-example\">leicht — lagan</div><div class=\"kurss-example\">der Eimer — kanta</div><div class=\"kurss-example\">wieviel (vifil) — koliko</div><div class=\"kurss-example\">wieviel Nadeln — koliko igala</div><div class=\"kurss-example\">hier (hir) — ovdje</div><div class=\"kurss-example\">dort — tamo</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izgovor</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä je preglas samoglasnika a i izgovara se kao kratko ili dugo zatvoreno e.</div><div class=\"kurss-example\">Primjeri: das Mädchen (methen), die Bänke (di benke), der Vater (der fater), die Väter (di feter).</div><div class=\"kurss-example\">ü je preglas samoglasnika u. Pri izgovoru usne treba jako zaokružiti i sa zaokruženim usnama pokušati izgovoriti i.</div><div class=\"kurss-example\">Primjeri: fünf, der Schlüssel (šlisel).</div><div class=\"kurss-example\">ö se izgovara sa zaokruženim usnama, uz pokušaj da se izgovori e: der Löffel.</div><div class=\"kurss-example\">Udvojeni samoglasnik označava dugi samoglasnik: leer (ler).</div><div class=\"kurss-example\">Diftong eu izgovara se kao oj: neun (nojn).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramatika i objašnjenja</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Naglašeni prefiks složenog glagola u prezentu odvaja se od glagola i stoji na kraju rečenice.</div><div class=\"kurss-example\">Primjeri: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Broj jedan ima oblik u sva tri roda kada se upotrebljava s imenicom: u muškom rodu ein, u ženskom rodu eine, u srednjem rodu ein.</div><div class=\"kurss-example\">Primjeri: ein Schüler — jedan učenik; eine Schülerin — jedna učenica; ein Kind — jedno dijete.</div><div class=\"kurss-example\">Brojevi: eins, zwei, drei, vier (fir), fünf, sechs (zeks), sieben (ziben), acht, neun (nojn), zehn (cen).</div><div class=\"kurss-example\">Glagol-spona u njemačkom ima oblik za jedninu i za množinu: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Pokazne zamjenice u bosanskom se mijenjaju po rodu i broju, a u njemačkom se u ovakvim rečenicama koristi samo jedan oblik, kao bosansko „to“ u „to je…“, „to su…“: das.</div><div class=\"kurss-example\">Primjeri: to je čekić — das ist ein Hammer; to je igla — das ist eine Nadel; to su čekići — das sind Hämmer; to su igle — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — kola i der Schlitten — saonice u bosanskom jeziku imaju samo množinu, a u njemačkom se ove riječi upotrebljavaju i u jednini i u množini.</div><div class=\"kurss-example\">Imenice muškog i srednjeg roda s nastavkom -er, -el, -en u množini često ne dobijaju nastavak.</div><div class=\"kurss-example\">Primjeri: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Imenice ženskog roda s nastavkom -el, -er u množini dobijaju -n.</div><div class=\"kurss-example\">Primjeri: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Izuzeci: die Mutter (majka) — die Mütter (majke); die Tochter (kćerka) — die Töchter (kćerke).</div><div class=\"kurss-example\">Neodređeni član nema množinu: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">U izjavnoj rečenici glagol u ulozi predikata stoji na drugom mjestu: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prevedi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 6: kartica za prevođenje\"><span class=\"lesson1-training-progress\">Lekcija 6 · Prevedi: 1 / 21</span><span class=\"lesson1-training-text\">Paul uzima olovku i crta.</span></button><p class=\"lesson1-training-hint\">Klikni na karticu da vidiš njemački prijevod. Nakon odgovora sljedeći klik prikazuje sljedeću karticu.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Lekcija 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akuzativ, sitzen, fragen i nastavak -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dijalozi / rečenice</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Riječi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zicen) — sjediti</div>\n        <div class=\"kurss-example\">fragen (fragen) — pitati</div>\n        <div class=\"kurss-example\">der Lehrer (der lerer) — učitelj</div>\n        <div class=\"kurss-example\">gut (gut) — dobro</div>\n        <div class=\"kurss-example\">wen (ven) — koga</div>\n        <div class=\"kurss-example\">loben — hvaliti</div>\n        <div class=\"kurss-example\">der Schüler (šiler) — učenik</div>\n        <div class=\"kurss-example\">klein — mali</div>\n        <div class=\"kurss-example\">groß (gros) — velik</div>\n        <div class=\"kurss-example\">die Lehrerin — učiteljica</div>\n        <div class=\"kurss-example\">die Schülerin — učenica</div>\n        <div class=\"kurss-example\">schlecht (šleht) — loše</div>\n        <div class=\"kurss-example\">tadeln — kuditi, koriti</div>\n        <div class=\"kurss-example\">oder (oder) — ili</div>\n        <div class=\"kurss-example\">das Kind (kint) — dijete</div>\n        <div class=\"kurss-example\">artig (artih) — poslušan</div>\n        <div class=\"kurss-example\">die Mutter — majka</div>\n        <div class=\"kurss-example\">lieben (liben) — voljeti</div>\n        <div class=\"kurss-example\">der Vater (fater) — otac</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izgovor</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz je udvojeni glas z i izgovara se kao c: sitzen (zicen).</div>\n        <div class=\"kurss-example\">U njemačkim riječima v se izgovara kao f: der Vater (fater).</div>\n        <div class=\"kurss-example\">ß se zove escet i izgovara se kao bosansko s: groß (gros), weiß (vajs).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativ i akuzativ</h4><div class=\"lesson1-grammar-note\">U bosanskom jeziku nominativ odgovara na pitanje ko? / šta?, a akuzativ na pitanje koga? / šta?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">U njemačkom je pitanje u nominativu wer? za osobe i was? za predmete.</div><div class=\"kurss-example\">U akuzativu je pitanje wen? za osobe i was? za predmete.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Promjena člana u akuzativu</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + akuzativ</h4><div class=\"lesson1-grammar-note\">Glagol fragen u njemačkom zahtijeva akuzativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nastavak -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Mnoge imenice ženskog roda izvode se nastavkom -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Mjesto glagola</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">U izjavnoj rečenici glagol stoji na drugom mjestu.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prevedi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 5: kartica za prevođenje\"><span class=\"lesson1-training-progress\">Lekcija 5 · Prevedi: 1 / 16</span><span class=\"lesson1-training-text\">Koga voli otac?</span></button><p class=\"lesson1-training-hint\">Klikni na karticu da vidiš njemački prijevod. Nakon odgovora sljedeći klik prikazuje sljedeću karticu.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Lekcija 4</h3>\n            <p class=\"kurss-lesson-intro\">Akuzativ, nehmen, hinlegen, hinausgehen i pridjevi.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dijalozi / rečenice</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Riječi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (nemen) — uzimati</div><div class=\"kurss-example\">er nimmt (nimt) — on uzima</div><div class=\"kurss-example\">der Federhalter (der federhalter) — držalo za pero</div><div class=\"kurss-example\">einen Federhalter — držalo za pero</div><div class=\"kurss-example\">zeigen — pokazivati</div><div class=\"kurss-example\">schwarz (švarc) — crn</div><div class=\"kurss-example\">weiß (vajs) — bijel</div><div class=\"kurss-example\">die Feder (di feder) — pero</div><div class=\"kurss-example\">eine Feder — pero</div><div class=\"kurss-example\">spitz (špic) — šiljat</div><div class=\"kurss-example\">hinlegen — odložiti</div><div class=\"kurss-example\">legt hin — odlaže</div><div class=\"kurss-example\">das Mädchen (methen) — djevojčica</div><div class=\"kurss-example\">das Messer — nož</div><div class=\"kurss-example\">ein Messer — nož</div><div class=\"kurss-example\">scharf — oštar</div><div class=\"kurss-example\">stumpf (štumpf) — tup</div><div class=\"kurss-example\">dann — onda, zatim</div><div class=\"kurss-example\">hinaus — van</div><div class=\"kurss-example\">hinausgehen — izlaziti, ići van</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izgovor</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nastavci -en, -er, -el su nenaglašeni, zato se e u njima slabo čuje: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">U njemačkom h može biti i glas i znak dužine prethodnog samoglasnika.</div><div class=\"kurss-example\">Kada je h znak dužine, ne izgovara se kao glas: nehmen (nemen).</div><div class=\"kurss-example\">Ako iza samoglasnika slijedi samo jedan suglasnik, samoglasnik se izgovara dugo: die (di) Feder (feder), den (den).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akuzativ</h4><div class=\"lesson1-grammar-note\">U ženskom i srednjem rodu akuzativ je jednak nominativu. Mijenja se samo muški rod.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Zamjenice</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — muški rod</div><div class=\"kurss-example\">sie — ženski rod</div><div class=\"kurss-example\">es — srednji rod</div><div class=\"kurss-example\">u množini — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Razdvojivi glagoli</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Pridjevi</h4><div class=\"lesson1-grammar-note\">Ako je pridjev u rečenici dio predikata, on se ne mijenja ni po rodu ni po broju.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Negacija s nicht</h4><div class=\"lesson1-grammar-note\">Ako nicht negira pridjev, stoji ispred riječi koju negira.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Imenice s nastavkom -chen i -lein srednjeg su roda: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prevedi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 4: kartica za prevođenje\"><span class=\"lesson1-training-progress\">Lekcija 4 · Prevedi: 1 / 16</span><span class=\"lesson1-training-text\">Djevojčica uzima držalo za pero.</span></button><p class=\"lesson1-training-hint\">Klikni na karticu da vidiš njemački prijevod. Nakon odgovora sljedeći klik prikazuje sljedeću karticu.</p></div></div></details>",
  "kurssLesson3": "            <h3>Lekcija 3</h3>\n            <p class=\"kurss-lesson-intro\">Treća lekcija: dijalozi, riječi, izgovor, gramatika i prevođenje.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dijalozi / rečenice</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Riječi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — ko</div><div class=\"kurss-example\">was — šta</div><div class=\"kurss-example\">hier — ovdje</div><div class=\"kurss-example\">dort — tamo</div><div class=\"kurss-example\">der Tisch — sto</div><div class=\"kurss-example\">ein Tisch — sto</div><div class=\"kurss-example\">die Bank — klupa</div><div class=\"kurss-example\">eine Bank — klupa</div><div class=\"kurss-example\">liegen — ležati</div><div class=\"kurss-example\">liegt hier ein Buch? — leži li ovdje knjiga?</div><div class=\"kurss-example\">das Buch — knjiga</div><div class=\"kurss-example\">ein Buch — knjiga</div><div class=\"kurss-example\">hängen — visjeti</div><div class=\"kurss-example\">das Bild — slika</div><div class=\"kurss-example\">ein Bild — slika</div><div class=\"kurss-example\">die Tafel — tabla</div><div class=\"kurss-example\">eine Tafel — tabla</div><div class=\"kurss-example\">wie — kakav, kakva</div><div class=\"kurss-example\">ist — je</div><div class=\"kurss-example\">dick — debeo</div><div class=\"kurss-example\">das Heft — sveska</div><div class=\"kurss-example\">ein Heft — sveska</div><div class=\"kurss-example\">dünn — tanak</div><div class=\"kurss-example\">niedrig — nizak</div><div class=\"kurss-example\">hoch — visok</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izgovor</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Dugi glas i u njemačkom se označava sa ie: liegen (ligen), hier (hir), wie (vi).</div><div class=\"kurss-example\">ck je udvojeno k: dick (dikk).</div><div class=\"kurss-example\">U pridjevima i prilozima nastavak -ig zvuči kao blago -ich: niedrig (nidrih).</div><div class=\"kurss-example\">Ako iza -ig dolazi e: -ige, onda se g izgovara kao jasno g: niedrige (nidrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Subjekt</h4><div class=\"lesson1-grammar-note\">Subjekt u njemačkom odgovara na pitanje wer? / was? i stoji u nominativu.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Sa wer? pita se za osobe.</div><div class=\"kurss-example\">Sa was? pita se za predmete.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Članovi</h4><div class=\"lesson1-grammar-note\">U njemačkom imenice imaju 3 roda: muški, ženski i srednji. Ispred imenica obično stoji riječca koja se zove član. Ta riječca se ne prevodi.</div><h5 class=\"lesson2-subtitle\">Određeni član</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">muški rod — der</div><div class=\"kurss-example\">ženski rod — die</div><div class=\"kurss-example\">srednji rod — das</div><div class=\"kurss-example\">U množini određeni član za sva tri roda glasi die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Neodređeni član</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">muški rod — ein</div><div class=\"kurss-example\">ženski rod — eine</div><div class=\"kurss-example\">srednji rod — ein</div><div class=\"kurss-example\">Neodređeni član nema množinu.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Vlastita imena</h4><div class=\"lesson1-grammar-note\">Ispred vlastitih imena član se ne upotrebljava.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Mjesto glagola</h4><div class=\"lesson1-grammar-note\">U izjavnoj rečenici glagol stoji na drugom mjestu.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Na njemačkom se za predmete koji su u uspravnom položaju kaže da stoje:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Za predmete koji su u vodoravnom položaju kaže se da leže:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Predmeti mogu i visjeti:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prevedi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 3: kartica za prevođenje\"><span class=\"lesson1-training-progress\">Lekcija 3 · Prevedi: 1 / 22</span><span class=\"lesson1-training-text\">Računaš li?</span></button><p class=\"lesson1-training-hint\">Klikni na karticu da vidiš njemački prijevod. Nakon odgovora sljedeći klik prikazuje sljedeću karticu.</p></div></div></details>",
  "kurssLesson7": "            <h3>Lekcija 7</h3>\n            <p class=\"kurss-lesson-intro\">Sedma lekcija: imperativ, učtivi oblik obraćanja i množina.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dijalozi / rečenice</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Riječi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — pjevati</div><div class=\"kurss-example\">singe — pjevaj</div><div class=\"kurss-example\">singt — pjevajte</div><div class=\"kurss-example\">singen Sie — pjevajte</div><div class=\"kurss-example\">das Lied (das lit) — pjesma</div><div class=\"kurss-example\">Sie — Vi</div><div class=\"kurss-example\">zählen — brojati</div><div class=\"kurss-example\">das Fräulein (frojlajn) — gospođica</div><div class=\"kurss-example\">der Müller — mlinar</div><div class=\"kurss-example\">öffnen — otvoriti</div><div class=\"kurss-example\">das Fenster (fenster) — prozor</div><div class=\"kurss-example\">alle — svi</div><div class=\"kurss-example\">der Spiegel (špigel) — ogledalo</div><div class=\"kurss-example\">der Lappen — krpa</div><div class=\"kurss-example\">der Spaten — lopata</div><div class=\"kurss-example\">der Besen — metla</div><div class=\"kurss-example\">die Schaufel — lopatica</div><div class=\"kurss-example\">die Schüssel — zdjela</div><div class=\"kurss-example\">das Zimmer — soba</div><div class=\"kurss-example\">das Ufer (ufer) — obala</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izgovor</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Na početku riječi ili sloga sp se izgovara kao šp: der Spiegel (der špigel).</div><div class=\"kurss-example\">sch se izgovara kao bosansko š: die Schaufel (di šaufel), die Schüssel (di šisel).</div><div class=\"kurss-example\">Diftong äu izgovara se kao bosansko „oj“: das Fräulein (das frojlajn).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Imperativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Imperativ u 2. licu jednine odgovara obliku glagola u 2. licu jednine bez ličnog nastavka -st, uz dodavanje nastavka -e.</div><div class=\"kurss-example\">Primjeri: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Vrlo često se nastavak -e ne upotrebljava ako je oblik imperativa bez njega jednosložan: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Imperativ množine</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Oblik imperativa u 2. licu množine jednak je 2. licu množine prezenta, ali se upotrebljava bez zamjenice.</div><div class=\"kurss-example\">Primjeri: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Učtivi oblik obraćanja sa Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Učtivi oblik obraćanja s „Vi“ jednak je 3. licu množine. Zamjenica Sie piše se velikim slovom i stoji iza glagola.</div><div class=\"kurss-example\">Primjeri: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Kod glagola öffnen radi lakšeg izgovora u 2. i 3. licu jednine i u 2. licu množine između osnove i nastavka umeće se e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Vježba</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 7: kartica za vježbu\"><span class=\"lesson1-training-progress\">Lekcija 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — pitati</span></button><p class=\"lesson1-training-hint\">Dodirni karticu da vidiš oblike imperativa.</p></div></div></details>",
  "kurssLesson1": "            <h3>Lekcija 1</h3>\n            <p class=\"kurss-lesson-intro\">Prva lekcija: glagoli u prezentu, riječi, izgovor, gramatika i prevođenje.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Glagoli u prezentu</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Glagoli i njihova konjugacija u prezentu.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — dolaziti</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>ja dolazim</span><span>du</span><strong>kommst</strong><span>ti dolaziš</span><span>er / sie</span><strong>kommt</strong><span>on / ona dolazi</span><span>wir</span><strong>kommen</strong><span>mi dolazimo</span><span>ihr</span><strong>kommt</strong><span>vi dolazite</span><span>sie / Sie</span><strong>kommen</strong><span>oni / Vi dolaze</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — ići</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>ja idem</span><span>du</span><strong>gehst</strong><span>ti ideš</span><span>er / sie</span><strong>geht</strong><span>on / ona ide</span><span>wir</span><strong>gehen</strong><span>mi idemo</span><span>ihr</span><strong>geht</strong><span>vi idete</span><span>sie / Sie</span><strong>gehen</strong><span>oni / Vi idu</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — stajati</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>ja stojim</span><span>du</span><strong>stehst</strong><span>ti stojiš</span><span>er / sie</span><strong>steht</strong><span>on / ona stoji</span><span>wir</span><strong>stehen</strong><span>mi stojimo</span><span>ihr</span><strong>steht</strong><span>vi stojite</span><span>sie / Sie</span><strong>stehen</strong><span>oni / Vi stoje</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — pjevati</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>ja pjevam</span><span>du</span><strong>singst</strong><span>ti pjevaš</span><span>er / sie</span><strong>singt</strong><span>on / ona pjeva</span><span>wir</span><strong>singen</strong><span>mi pjevamo</span><span>ihr</span><strong>singt</strong><span>vi pjevate</span><span>sie / Sie</span><strong>singen</strong><span>oni / Vi pjevaju</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Primjeri</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Riječi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Približan izgovor riječi dat je u zagradama bosanskim slovima.<br>To važi i za sljedeće lekcije.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vir) — mi</div><div class=\"kurss-example\">U riječi „wir“ slovo i izgovara se dugo.</div><div class=\"kurss-example\">kommen (komen) — dolaziti</div><div class=\"kurss-example\">gehen (ge-en) — ići</div><div class=\"kurss-example\">stehen (šte-en) — stajati</div><div class=\"kurss-example\">singen (zingen) — pjevati</div><div class=\"kurss-example\">du (du) kommst — ti dolaziš</div><div class=\"kurss-example\">er (er) kommt — on dolazi</div><div class=\"kurss-example\">sie (zi) kommt — ona dolazi</div><div class=\"kurss-example\">wer (ver) — ko?</div><div class=\"kurss-example\">ja (ja) — da</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Izgovor</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Pravilan izgovor riječi, zapisan bosanskim slovima, dat je u lekcijama.</div><div class=\"kurss-example\">Wir (vir) — mi. U riječi wir i se uvijek izgovara dugo.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitiv</h4><div class=\"lesson1-grammar-note\">Osnovni oblik glagola. Infinitiv obično završava na -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Nastavci u prezentu</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Ukloni <span class=\"lesson1-ending-accent\">-en</span> iz osnovnog oblika glagola i dodaj nastavak.</strong></p><p>Primjer: kommen → komm + nastavak</p><div class=\"lesson1-ending-process\" aria-label=\"Kako se tvore nastavci u prezentu\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>osnovni oblik</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>ukloni <span class=\"lesson1-ending-accent\">-en</span></strong><span>ostaje osnova</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>osnova</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>dodaj nastavak</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Primjeri</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Upitne rečenice</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>U njemačkoj upitnoj rečenici glagol se obično premješta na prvo mjesto.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Na bosanskom:<br>Ti dolaziš.<br>Dolaziš li ti?</div><div class=\"kurss-example\">Na njemačkom:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — ti dolaziš<br>kommst du? — dolaziš li?</div><div class=\"kurss-example\">er singt — on pjeva<br>singt er? — pjeva li on?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Razlika u licu</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — on dolazi</div><div class=\"kurss-example\">sie kommt — ona dolazi</div><div class=\"kurss-example\">sie kommen — oni / one dolaze</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Prevedi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lekcija 1: kartica za vježbanje\">\n                    <span class=\"lesson1-training-progress\">Lekcija 1 · Prevedi: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Dolaziš li?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klikni na karticu da vidiš njemački prijevod. Nakon odgovora sljedeći klik prikazuje sljedeću karticu.</p>\n                </div>\n              </div>\n            </details>"
};

